  const mask = new Array(n).fill(0);
  const queue = [0];
  for (let i = 0; i < queue.length; i++) {
    const node = queue[i];
    for (const child of children[node]) {
      const bit = 1 << (s.charCodeAt(child) - 97);
      mask[child] = mask[node] ^ bit;
      queue.push(child);
    }
  }
  const seen = new Map();
  let count = 0;
  for (let node = 0; node < n; node++) {
    const current = mask[node];
    count += seen.get(current) ?? 0;
    for (let letter = 0; letter < 26; letter++) {
      count += seen.get(current ^ (1 << letter)) ?? 0;
    }
    seen.set(current, (seen.get(current) ?? 0) + 1);
  }
  return count;
}

