function countPalindromePaths(parent, s) {
  // For every pair, collect the edge letters by climbing both ends to their meeting point.
  const n = parent.length;
  const depth = new Array(n).fill(-1);
  const depthOf = (v) => {
    if (depth[v] >= 0) return depth[v];
    depth[v] = v === 0 ? 0 : depthOf(parent[v]) + 1;
    return depth[v];
  };
  let total = 0;
  for (let u = 0; u < n; u++) {
    for (let v = u + 1; v < n; v++) {
      const freq = new Array(26).fill(0);
      let a = u, b = v;
      while (a !== b) {
        if (depthOf(a) >= depthOf(b)) { freq[s.charCodeAt(a) - 97]++; a = parent[a]; }
        else { freq[s.charCodeAt(b) - 97]++; b = parent[b]; }
      }
      const odd = freq.filter(f => f % 2 === 1).length;
      if (odd <= 1) total++;
    }
  }
  return total;
}

